import type { DownloadControl, DownloadItem, DownloadSource, SourceQueue, ControlResult } from "./download-types";
import { Alert, Badge, Button, Group, Progress, Stack, Text } from "@mantine/core";
import { useWidgetAction, useWidgetCapabilities, useWidgetHost, useWidgetQuery, useWidgetServices } from "@homarr/widget-sdk";
const rate = (value:number|undefined) => `${((value ?? 0)/1048576).toFixed(1)} MiB/s`;
export function DownloadSourceRegion({source,filter,sort}:{source:DownloadSource;filter:string;sort:string}) {
  const host = useWidgetHost();
  const services = useWidgetServices();
  const capabilities = useWidgetCapabilities();
  const query = useWidgetQuery<SourceQueue>("queue",{connection:source.connection},{refetchInterval:10000});
  const action = useWidgetAction<ControlResult,DownloadControl>("control");
  const status = query.data?.data.status;
  const error = query.error ?? action.error;
  const run = (input:DownloadControl) => {void action.mutateAsync(input).catch(() => undefined);};
  const canRun = (input:DownloadControl) => !host.isEditMode && !action.isPending && capabilities.canRun("control",input);
  const remove = async (item:DownloadItem) => {
    const input:DownloadControl = {connection:source.connection,operation:"deleteItem",itemId:item.id};
    if (!canRun(input)) return;
    if (await services.confirm({title:"Remove download",message:`Remove ${item.name} from ${source.label}? Downloaded files will be kept.`,destructive:true})) run(input);
  };
  const rows = query.data?.data.items ?? [];
  let items = rows.filter((item) => item.name.toLocaleLowerCase().includes(filter.toLocaleLowerCase()));
  if (sort === "progress") items = items.toSorted((a,b) => b.progress-a.progress);
  if (sort === "name") items = items.toSorted((a,b) => a.name.localeCompare(b.name));
  if (host.displayMode === "compact") items = items.slice(0,3);
  const pause:DownloadControl = {connection:source.connection,operation:"pause"};
  const resume:DownloadControl = {connection:source.connection,operation:"resume"};
  return <Stack gap="xs" component="section" aria-label={source.label} style={{border:"1px solid var(--mantine-color-default-border)",borderRadius:8,padding:10}}>
    <Group justify="space-between"><Text size="sm" fw={600}>{source.label} · {rows.length}</Text>{status && <Badge color={status.paused ? "yellow" : "blue"}>{status.paused ? "Paused" : rate(status.rates.down)}</Badge>}</Group>
    {error && <Alert color="yellow" title={source.label}>{error.message}<Button size="compact-xs" variant="subtle" onClick={() => {action.reset();void query.refetch();}}>Retry this client</Button></Alert>}
    {action.isPending && <Text size="xs" c="dimmed" role="status">Updating this client…</Text>}
    {query.isPending && <Text size="xs" c="dimmed">Loading this client's queue…</Text>}
    {host.displayMode === "advanced" && <Group gap="xs"><Button size="compact-xs" variant="light" disabled={!canRun(pause)} onClick={() => run(pause)}>Pause this client</Button><Button size="compact-xs" variant="light" disabled={!canRun(resume)} onClick={() => run(resume)}>Resume this client</Button></Group>}
    {items.map((item) => {
      const toggle:DownloadControl = {connection:source.connection,operation:item.state === "paused" ? "resumeItem" : "pauseItem",itemId:item.id};
      const deletion:DownloadControl = {connection:source.connection,operation:"deleteItem",itemId:item.id};
      return <Stack key={`${source.connection}:${item.id}`} gap={4}>
        <Group justify="space-between" wrap="nowrap"><Text size="sm" truncate>{item.name}</Text><Badge size="xs">{item.state}</Badge></Group>
        <Progress aria-label={`${source.label}: ${item.name} progress`} value={item.progress*100} />
        <Group justify="space-between"><Text size="xs" c="dimmed">{Math.round(item.progress*100)}% · {rate(item.downSpeed)}</Text>{host.displayMode === "advanced" && <Group gap="xs"><Button size="compact-xs" variant="subtle" disabled={!canRun(toggle)} onClick={() => run(toggle)}>{item.state === "paused" ? "Resume" : "Pause"}</Button><Button size="compact-xs" color="red" variant="subtle" disabled={!canRun(deletion)} onClick={() => void remove(item)}>Remove</Button></Group>}</Group>
      </Stack>;
    })}
    {!query.isPending && !query.error && items.length === 0 && <Text size="xs" c="dimmed">No downloads match this client view.</Text>}
    {action.data?.ok && <Text size="xs" c="green">{source.label}: {action.data.operation} completed</Text>}
  </Stack>;
}

