import type { BatchControl, BatchResult, DownloadConnection, DownloadSource } from "./download-types";
import { Alert, Button, Group, MultiSelect, Select, Stack, Text, TextInput } from "@mantine/core";
import { useWidgetAction, useWidgetCapabilities, useWidgetCommands, useWidgetHost, useWidgetQuery, useWidgetState } from "@homarr/widget-sdk";
import { DownloadSourceRegion } from "./download-source";
export default function Downloads() {
  const host = useWidgetHost();
  const sources = useWidgetQuery<DownloadSource[]>("sources",{}, {staleTime:60000});
  const capabilities = useWidgetCapabilities();
  const batch = useWidgetAction<BatchResult,BatchControl>("controlBatch");
  const [filter,setFilter] = useWidgetState("filter","");
  const [sort,setSort] = useWidgetState("sort","queue");
  const [selection,setSelection] = useWidgetState<DownloadConnection[]>("batch-clients",[]);
  const available = sources.data ?? [];
  const targets = selection.filter((name) => available.some((source) => source.connection === name));
  const all = available.map((source) => source.connection);
  const canRun = (input:BatchControl) => input.connections.length > 0 && !host.isEditMode && !batch.isPending && capabilities.canRun("controlBatch",input);
  const run = (input:BatchControl) => {void batch.mutateAsync(input).catch(() => undefined);};
  const pauseAll:BatchControl = {connections:all,operation:"pause"};
  const resumeAll:BatchControl = {connections:all,operation:"resume"};
  const pauseSelected:BatchControl = {connections:targets,operation:"pause"};
  const resumeSelected:BatchControl = {connections:targets,operation:"resume"};
  useWidgetCommands([{id:"pause-all",label:"Pause all download clients",disabled:!canRun(pauseAll),run:() => run(pauseAll)},{id:"resume-all",label:"Resume all download clients",disabled:!canRun(resumeAll),run:() => run(resumeAll)}]);
  return <Stack p="sm" gap="sm" h="100%" style={{overflow:"auto"}}>
    <Text fw={600}>Downloads · {available.length} clients</Text>
    {sources.error && <Alert color="red">{sources.error.message}<Button size="xs" variant="subtle" onClick={() => void sources.refetch()}>Retry setup</Button></Alert>}
    {host.displayMode === "advanced" && <>
      <Group><TextInput label="Filter downloads" value={filter} onChange={(event) => setFilter(event.currentTarget.value)} /><Select label="Sort" value={sort} onChange={(value) => setSort(value ?? "queue")} data={[{value:"queue",label:"Queue"},{value:"progress",label:"Progress"},{value:"name",label:"Name"}]} /></Group>
      <Group gap="xs"><Button size="compact-xs" disabled={!canRun(pauseAll)} onClick={() => run(pauseAll)}>Pause all clients</Button><Button size="compact-xs" disabled={!canRun(resumeAll)} onClick={() => run(resumeAll)}>Resume all clients</Button></Group>
      {available.length > 1 && <Group align="end"><MultiSelect label="Batch targets" data={available.map((source) => ({value:source.connection,label:source.label}))} value={selection} onChange={(values) => setSelection(all.filter((connection) => values.includes(connection)))} /><Button size="compact-xs" variant="light" disabled={!canRun(pauseSelected)} onClick={() => run(pauseSelected)}>Pause selected</Button><Button size="compact-xs" variant="light" disabled={!canRun(resumeSelected)} onClick={() => run(resumeSelected)}>Resume selected</Button></Group>}
    </>}
    {batch.isPending && <Text size="xs" c="dimmed" role="status">Updating selected clients…</Text>}
    {batch.error && <Alert color="red">{batch.error.message}</Alert>}
    {batch.data && <Alert color={batch.data.failed ? "yellow" : "green"} title={`${batch.data.succeeded} succeeded · ${batch.data.failed} failed`}>
      {batch.data.results.map((result) => <Text size="xs" key={result.connection}>{available.find((source) => source.connection === result.connection)?.label ?? result.connection}: {result.ok ? `${result.operation} completed` : result.error}</Text>)}
    </Alert>}
    {available.map((source) => <DownloadSourceRegion key={source.connection} source={source} filter={filter} sort={sort} />)}
    {!sources.isPending && !sources.error && available.length === 0 && <Text c="dimmed">Bind a download client to get started.</Text>}
  </Stack>;
}
